use hec_native_ic::fp::Fp;
pub fn rank(mut a:Vec<Vec<u64>>, f:&Fp)->usize {if a.is_empty(){return 0}let mut r=0;for j in 0..a[0].len(){let Some(i)=(r..a.len()).find(|&i|a[i][j]!=0)else{continue};a.swap(i,r);let z=f.inv(a[r][j]);for k in j..a[r].len(){a[r][k]=f.mul(a[r][k],z)}for i in 0..a.len(){if i!=r{let z=a[i][j];for k in j..a[i].len(){a[i][k]=f.sub(a[i][k],f.mul(z,a[r][k]))}}}r+=1;if r==a.len(){break}}r}
fn root(p:&mut[usize],i:usize)->usize{if p[i]!=i{p[i]=root(p,p[i])}p[i]}
fn components(b:&[Vec<u64>],cols:&[bool],f:&Fp)->Vec<Vec<usize>>{let n=b.len();let mut p:Vec<_>=(0..n).collect();let mut grounded=vec![false;n];for j in 0..cols.len(){if !cols[j]{continue}let hits:Vec<_>=(0..n).filter(|&i|b[i][j]!=0).collect();match hits.as_slice(){[]=>{},[i]=>{grounded[*i]=true},[i,k]=>{assert_eq!(f.add(b[*i][j],b[*k][j]),0);let a=root(&mut p,*i);let z=root(&mut p,*k);p[a]=z},_=>panic!("not incidence")}}
let mut members=vec![vec![];n];let mut ground=vec![false;n];for i in 0..n{let r=root(&mut p,i);members[r].push(i);ground[r]|=grounded[i]}members.into_iter().enumerate().filter(|(i,v)|!v.is_empty()&&!ground[*i]).map(|(_,v)|v).collect()}
pub fn check(b:&[Vec<u64>],anchors:&[bool],ell:u64)->(usize,usize,usize,usize,usize){let f=Fp::new(ell);if b.is_empty(){return(0,0,0,0,0)}let m=anchors.len();let off:Vec<_>=anchors.iter().map(|x|!x).collect();let cs=components(b,&off,&f);let full=components(b,&vec![true;m],&f);let delta=|cs:&Vec<Vec<usize>>|usize::from(cs.iter().any(|v|v.len()as u64%ell!=0));let d=delta(&cs);let df=delta(&full);let expected=(cs.len()-d)-(full.len()-df);
let w:Vec<Vec<u64>>=cs.iter().map(|v|{let mut out=vec![0;m];for &i in v{for j in 0..m{if anchors[j]{out[j]=f.add(out[j],b[i][j])}}}out}).collect();let mut out=vec![];
if let Some(p)=cs.iter().position(|v|v.len()as u64%ell!=0){let inv=f.inv(cs[p].len()as u64%ell);for j in 0..cs.len(){if j==p{continue}let z=f.mul(cs[j].len()as u64%ell,inv);out.push((0..m).map(|k|f.sub(w[j][k],f.mul(z,w[p][k]))).collect::<Vec<_>>())}}else{out=w;}
let r:Vec<Vec<u64>>=b[1..].iter().map(|v|(0..m).map(|j|f.sub(v[j],b[0][j])).collect()).collect();let ro:Vec<Vec<u64>>=r.iter().map(|v|v.iter().enumerate().filter(|(j,_)|off[*j]).map(|(_,x)|*x).collect()).collect();let rr=rank(r.clone(),&f);let r_off=rank(ro,&f);let got=rank(out.clone(),&f);assert_eq!(got,rr-r_off,"independent full/off rank");assert_eq!(got,expected,"component dimension");for v in &out{for j in 0..m{if off[j]{assert_eq!(v[j],0)}}}let mut joined=r;joined.extend(out.iter().cloned());assert_eq!(rank(joined,&f),rr,"row containment");(got,cs.len(),full.len(),out.len(),usize::from(cs.iter().any(|v|v.len()as u64%ell==0)))}
